 auto next=resumed->Request("local",false,error);check(pump(*resumed,[&]{auto s=resumed->Status(next);return s&&s->state=="active";}),"cold retained region activates");auto* actor=cold.RuntimeCharacter(resumed->Resolve("local",2));check(actor&&glm::length(cold.Settings().worldOrigin+V(actor->position)-expected)<.0005,"cold retained motor endpoint uses the original absolute location");
